{
  "root_causes": [
    {
      "service": "ts-order-other-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, COUNT(*) n, ROUND(AVG(duration)/1e6,2) avg_ms, ROUND(quantile_cont(duration,0.95)/1e6,1) p95 FROM abnormal_traces WHERE attr_span_kind='Client' AND span_name LIKE 'SELECT%' AND service_name='ts-order-other-service' GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, span_name, COUNT(*), ROUND(AVG(duration)/1e6,2), ROUND(quantile_cont(duration,0.95)/1e6,1) FROM normal_traces WHERE attr_span_kind='Client' AND span_name LIKE 'SELECT%' AND service_name='ts-order-other-service' GROUP BY 1,2,3", "claim": "ts-order-other-service SELECT ts.orders_other DB spans rose from about 0.29 ms average to about 88 ms (p95 0.4 to 416 ms)."},
        {"kind": "trace", "sql": "SELECT service_name, attr_span_kind, span_name, COUNT(*) n, ROUND(AVG(duration)/1e6,1) avg_ms, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms, ROUND(AVG(CASE WHEN attr_status_code='Error' THEN 1.0 ELSE 0 END),3) err FROM abnormal_traces WHERE service_name='ts-order-other-service' GROUP BY 1,2,3 HAVING COUNT(*)>10 ORDER BY p95_ms DESC", "claim": "ts-order-other-service server and repository spans are slow (p95 about 2.3 s) with zero error status, consistent with slow DB calls."},
        {"kind": "metric", "sql": "SELECT metric, COUNT(*) n, ROUND(AVG(value),3) avg_v, ROUND(MAX(value),3) max_v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-order-other%' AND metric IN ('container.cpu.usage','container.memory.usage') GROUP BY 1", "claim": "ts-order-other-service pod CPU and memory stay low (cpu about 0.02 cores, memory about 576 MB), so the slowness is not resource saturation."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-other-service",
      "to": "ts-admin-order-service",
