      ]
    },
    {
      "from": "ts-admin-order-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, attr_span_kind, span_name, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE span_name IN ('GET /api/v1/adminorderservice/adminorder','GET') AND service_name IN ('ts-admin-order-service','ts-ui-dashboard') AND attr_span_kind IN ('Server','Client') GROUP BY 1,2,3", "claim": "User-facing GET /api/v1/adminorderservice/adminorder at ts-ui-dashboard has p95 about 878 ms, tracking the slow admin-order calls."}
      ]
